function homeView() { return `<section class="hero"><div class="hero-copy"><h1>A little folded.<br>A lot unexpected.</h1><p>A poetry game for people who don’t have to be poets. Write a line, pass it on, unfold it together.</p><div class="button-row">${goButton('Host a game', 'host-entry')}${goButton('Join a game', 'join-entry', 'secondary')}</div><p class="fine-print">2–8 humans. Nine little lines. No account needed.</p></div>${paperToy()}</section><section class="how-strip" aria-label="How a game unfolds"><article><span class="fold-number">1</span><div><h3>Find your people</h3><p>Invite friends to the same room. Anyone can be a writer.</p></div></article><article><span class="fold-number">2</span><div><h3>Follow one line</h3><p>Only the line before yours is visible. The rest stays folded.</p></div></article><article><span class="fold-number">3</span><div><h3>Open a surprise</h3><p>Read the complete poems aloud. Keep the ones you love.</p></div></article></section>`; }
