function emptyView(title, detail, action = 'Go home', id = 'home', second, secondId) { return `<section class="empty-layout">${paperToy(true)}<h1>${title}</h1><p>${detail}</p><div class="button-row">${goButton(action,id)}${second ? goButton(second,secondId,'secondary') : ''}</div></section>`; }
